CREATE DATABASE IF NOT EXISTS scholarhub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE scholarhub;

CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('student','admin') NOT NULL DEFAULT 'student',target_country VARCHAR(100) NULL,study_level VARCHAR(80) NULL,field VARCHAR(150) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scholarships (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL UNIQUE,provider VARCHAR(255) NOT NULL,country VARCHAR(100) NOT NULL,study_level VARCHAR(150) NULL,fields TEXT NULL,funding_type VARCHAR(100) NULL,official_url TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS universities (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,country VARCHAR(100) NOT NULL,city VARCHAR(100) NULL,description TEXT NULL,official_url TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fields (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,description TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);


ON DUPLICATE KEY UPDATE title=VALUES(title);


ON DUPLICATE KEY UPDATE description=VALUES(description);
